using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9+: ZipArchiveEntry now respects the UTF-8 flag and writes
        // non-ASCII names as UTF-8 by default. The legacy Java consumer
        // expects Shift-JIS, so we must explicitly specify the encoding.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding(932)
            ?? Encoding.UTF8;
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9+: [FromKeyedServices] no longer falls back to non-keyed
// registrations — it throws InvalidOperationException. Register as keyed.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

